class Visual final : public Scene {
  struct Star { float radius, angle, lift, drift; int group; };
  std::vector<Star> stars;
  float turn = 0, breath = 0;
 public:
  void reset(uint32_t seed) override {
    Random rng(seed); stars.clear(); stars.reserve(1500); turn=0; breath=0;
    for(int i=0;i<1500;i++) {
      float r=std::sqrt(rng.unit()); int arm=i%4;
      stars.push_back({r, float(arm*pi/2)+r*5.8f+(rng.unit()-.5f)*(.25f+r*.8f),
        (rng.unit()-.5f)*(.018f+r*.035f), .7f+rng.unit()*.6f, i%9});
    }
  }
  void update(const Frame& f) override {
    turn += float(f.delta)*f.speed*.06f;
    float target=f.music.energy;
    breath += (target-breath)*float(1-std::exp(-f.delta*3));
  }
  void render(const Frame& f, Canvas& c) const override {
    Paint sky=Paint::radial({f.width*.5f,f.height*.47f},f.height*.75f,
      {Color::argb(0xff151031),Color::argb(0xff03040d)});
    c.rect({0,0,f.width,f.height},sky);
    c.save(); c.translate(f.width*.5f,f.height*.48f); c.rotate(-.38f);
    float scale=std::min(f.width*.62f,f.height*.42f)*(1+breath*.045f);
    Paint haze=Paint::radial({0,0},scale*.8f,{Color{.24f,.1f,.5f,.2f},Color{.08f,.02f,.3f,0}});
    haze.blend=Blend::plus; c.rect({-scale,-scale,scale*2,scale*2},haze);
    for(int group=0;group<9;group++) {
      std::vector<Vec2> batch;batch.reserve(170);
      for(const auto& s:stars) if(s.group==group) {
        float a=s.angle+turn*s.drift;
        batch.push_back({std::cos(a)*s.radius*scale,
          std::sin(a)*s.radius*scale*.49f+s.lift*scale});
      }
      Paint p;p.blend=Blend::plus;
      p.color=group%3==0?Color{.58f,.69f,1,.65f}:group%3==1?Color{1,.67f,.48f,.6f}:Color{.9f,.72f,1,.72f};
      c.points(batch,.55f+(group/3)*.5f,p);
    }
    Paint core=Paint::radial({0,0},scale*.28f,{Color{1,.87f,.68f,.92f},Color{.65f,.34f,.75f,.22f},Color{.2f,.1f,.6f,0}},{0,.22f,1});
    core.blend=Blend::screen;c.circle({0,0},scale*.28f,core);c.restore();
  }
};

class Visual final : public Scene {
  struct Particle { float x,y,velocity,phase; };
  std::vector<Particle> particles;
  float impulse=0;
 public:
  void reset(uint32_t seed) override {
    Random r(seed);particles.clear();impulse=0;
    for(int i=0;i<240;i++)particles.push_back({r.unit(),r.unit(),.02f+r.unit()*.03f,r.unit()*6.28f});
  }
  void update(const Frame& f) override {
    for(const auto& event:f.music.events[0])impulse=std::max(impulse,event.strength);
    impulse*=float(std::exp(-f.delta*2.2));
    for(auto& p:particles){p.y-=p.velocity*float(f.delta)*f.speed*(1+impulse*3);
      if(p.y<-.03f)p.y+=1.06f;p.phase+=float(f.delta)*.3f;}
  }
  void render(const Frame& f, Canvas& c) const override {
    for(int group=0;group<4;group++){
      std::vector<Vec2> points;
      for(size_t i=group;i<particles.size();i+=4){const auto& p=particles[i];
        points.push_back({(p.x+std::sin(p.phase+p.y*3)*.02f)*f.width,p.y*f.height});}
      Paint paint;paint.blend=Blend::plus;paint.color={1,.65f+group*.05f,.25f+group*.12f,.35f+group*.16f};
      c.points(points,.8f+group*.45f+impulse*.4f,paint);
    }
  }
};

class Visual final : public Scene {
  struct Star { float x, y, z0, cycle; };
  std::vector<Star> stars;
 public:
  void reset(uint32_t seed) override {
    Random rng(seed);
    stars.clear(); stars.reserve(621);
    for (int i = 0; i < 621; i++) {
      Star s;
      s.x = (rng.unit() - 0.5f) * 2.2f;
      s.y = (rng.unit() - 0.5f) * 2.2f;
      s.z0 = rng.unit() * 2.2f + 0.05f;
      s.cycle = 2.2f + 1.2f;
      stars.push_back(s);
    }
  }
  void update(const Frame& f) override { (void)f; }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float cx = w * 0.5f, cy = h * 0.5f;
    float t = float(f.time) * f.speed;
    float rate = (1.1f + std::sin(t * 0.25f) * 0.55f) * (1.0f + f.music.energy * 0.8f);
    if (f.reducedMotion) rate *= 0.4f;
    float travel = t * rate * 0.96f;
    float boost = (0.7f + 0.5f * f.music.energy + 0.4f * f.music.bass) * f.intensity;
    Paint bg; bg.color = Color::argb(0xff02020c);
    c.rect({0, 0, w, h}, bg);
    Path lanes[3];
    std::vector<Vec2> heads[3];
    for (int i = 0; i < 3; i++) heads[i].reserve(240);
    for (size_t idx = 0; idx < stars.size(); idx++) {
      const Star& s = stars[idx];
      float z = std::fmod(s.z0 - travel, s.cycle);
      if (z < 0.04f) z += s.cycle;
      float x1 = cx + (s.x / z) * 0.75f;
      float y1 = cy + (s.y / z) * 0.75f;
      if (x1 < -80 || x1 > w + 80 || y1 < -80 || y1 > h + 80) continue;
      float tail = z + 0.11f;
      int lane = int(idx % 3);
      lanes[lane].moveTo(cx + (s.x / tail) * 0.75f, cy + (s.y / tail) * 0.75f);
      lanes[lane].lineTo(x1, y1);
      heads[lane].push_back({x1, y1});
    }
    for (int lane = 0; lane < 3; lane++) {
      Paint p; p.blend = Blend::plus;
      if (lane == 0) { p.color = {1, 1, 1, 0.9f * boost}; p.strokeWidth = 1.7f; }
      else if (lane == 1) { p.color = {0.749f, 0.894f, 1, 0.55f * boost}; p.strokeWidth = 1.1f; }
      else { p.color = {1, 0.839f, 0.941f, 0.55f * boost}; p.strokeWidth = 1.1f; }
      p.strokeCap = 1; p.strokeJoin = 1;
      c.path(lanes[lane], p);
      if (!heads[lane].empty()) {
        Paint hp; hp.blend = Blend::plus;
        hp.color = {1, 1, 1, 0.85f * boost};
        c.points(heads[lane], 0.85f, hp);
      }
    }
    Paint glow = Paint::radial({cx, cy}, std::min(w, h) * 0.45f,
      {{0.549f, 0.745f, 1, 0.28f * boost}, {0, 0, 0, 0}});
    glow.blend = Blend::plus;
    c.rect({0, 0, w, h}, glow);
  }
};

class Visual final : public Scene {
  std::vector<float> ridge;
  float pulse = 0;
  static float vhash(int x, int y) {
    uint32_t h = uint32_t(x) * 374761393u + uint32_t(y) * 668265263u;
    h = (h ^ (h >> 13)) * 1274126177u; h ^= h >> 16;
    return float(h & 0xffffu) / 65535.0f;
  }
  static float vnoise(float x, float y) {
    int xi = int(std::floor(x)), yi = int(std::floor(y));
    float xf = x - float(xi), yf = y - float(yi);
    float u = xf * xf * (3.0f - 2.0f * xf), v = yf * yf * (3.0f - 2.0f * yf);
    float a = vhash(xi, yi), b = vhash(xi + 1, yi);
    float c = vhash(xi, yi + 1), d = vhash(xi + 1, yi + 1);
    return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
  }
 public:
  void reset(uint32_t seed) override {
    (void)seed; ridge.clear(); pulse = 0;
  }
  void update(const Frame& f) override {
    if (ridge.size() != 30) {
      ridge.resize(30);
      for (int i = 0; i < 30; i++)
        ridge[i] = (vnoise(float(i) * 0.4f, 1.0f) * 0.5f + vnoise(float(i) * 0.9f, 7.0f) * 0.5f);
    }
    for (const auto& band : f.music.events)
      for (const auto& e : band) pulse += e.strength;
    pulse *= float(std::exp(-f.delta * 4.0));
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = float(f.time) * f.speed;
    float hz = h * 0.56f;
    float glowBoost = (0.7f + 0.6f * f.music.bass + 0.8f * pulse) * f.intensity;
    Paint sky = Paint::linear({0, 0}, {0, hz},
      {Color::argb(0xff160034), Color::argb(0xff4a0a6b), Color::argb(0xffff4d78)}, {0, 0.55f, 1.0f});
    c.rect({0, 0, w, hz}, sky);
    float sr = std::min(w, h) * 0.22f;
    float sunCx = w * 0.5f, sunCy = hz - sr * 0.15f;
    c.save();
    Path sunClip; sunClip.circle({sunCx, sunCy}, sr);
    c.clip(sunClip);
    Paint sun = Paint::linear({0, hz - sr * 1.3f}, {0, hz + 4.0f},
      {Color::argb(0xfffff36b), Color::argb(0xffff8a3d), Color::argb(0xffff2e9a)}, {0, 0.45f, 1.0f});
    c.rect({sunCx - sr, hz - sr * 1.3f, sr * 2.0f, sr * 2.0f}, sun);
    Paint bar; bar.color = Color::argb(0xff160034);
    float lane = sr * 0.14f;
    float off = std::fmod(t * 14.0f, lane);
    for (int i = 0; i < 9; i++) {
      float y = hz - sr * 0.9f + float(i) * lane + off;
      c.rect({sunCx - sr, y, sr * 2.0f, float(i) * 0.55f + 1.5f}, bar);
    }
    c.restore();
    Path mtn; mtn.moveTo(0, hz);
    for (int i = 0; i < 30; i++)
      mtn.lineTo(float(i) / 29.0f * w, hz - ridge[i] * h * 0.16f);
    mtn.lineTo(w, hz); mtn.close();
    Paint mfill; mfill.color = Color::argb(0xff0d0020);
    c.path(mtn, mfill);
    Paint mstroke; mstroke.color = {1, 0.435f, 0.847f, 0.9f * f.intensity};
    mstroke.strokeWidth = 1.0f;
    c.path(mtn, mstroke);
    Paint floor = Paint::linear({0, hz}, {0, h},
      {Color::argb(0xff12002b), Color::argb(0xff2a004d)});
    c.rect({0, hz, w, h - hz}, floor);
    Path grid;
    for (int i = -9; i <= 9; i++) {
      grid.moveTo(w * 0.5f, hz);
      grid.lineTo(w * 0.5f + float(i) * w * 0.34f, h);
    }
    float speed = std::fmod(t * 0.55f, 1.0f);
    for (int i = 0; i < 16; i++) {
      float k = (float(i) + speed) / 16.0f;
      float y = hz + (h - hz) * k * k * 1.02f;
      if (y > h) continue;
      grid.moveTo(0, y); grid.lineTo(w, y);
    }
    Paint gp; gp.color = {0, 1, 0.965f, 0.75f * f.intensity};
    gp.strokeWidth = 1.1f;
    c.path(grid, gp);
    Paint hg = Paint::linear({0, hz - 26.0f}, {0, hz + 26.0f},
      {{1, 0.18f, 0.604f, 0}, {1, 0.47f, 0.784f, 0.35f * glowBoost}, {0, 1, 0.965f, 0}}, {0, 0.5f, 1.0f});
    hg.blend = Blend::plus;
    c.rect({0, hz - 26.0f, w, 52.0f}, hg);
  }
};

class Visual final : public Scene {
  std::vector<Vec2> buckets[6];
  float step = 12.0f, cols = 0, rows = 0, lastW = 0, lastH = 0, lastDetail = -1.0f;
  void build(float w, float h, float detail) {
    step = std::max(9.0f, std::min(w, h) / (18.0f + 16.0f * detail));
    cols = std::ceil(w / step) + 1.0f;
    rows = std::ceil(h / step) + 1.0f;
  }
 public:
  void reset(uint32_t seed) override {
    (void)seed;
    for (int i = 0; i < 6; i++) buckets[i].clear();
    lastW = 0; lastH = 0; lastDetail = -1.0f;
  }
  void update(const Frame& f) override {
    float w = f.width, h = f.height;
    float t = float(f.time) * f.speed;
    if (w != lastW || h != lastH || f.detail != lastDetail) {
      build(w, h, f.detail);
      lastW = w; lastH = h; lastDetail = f.detail;
    }
    float amp = 1.0f + f.music.bass * 0.6f;
    float s1x = w * (0.5f + std::sin(t * 0.35f) * 0.32f);
    float s1y = h * (0.35f + std::sin(t * 0.27f + 1.0f) * 0.2f);
    float s2x = w * (0.5f + std::sin(t * 0.31f + 2.4f) * 0.34f);
    float s2y = h * (0.68f + std::sin(t * 0.23f + 3.0f) * 0.2f);
    for (int i = 0; i < 6; i++) buckets[i].clear();
    for (int j = 0; j < int(rows); j++) {
      float y = float(j) * step;
      for (int i = 0; i < int(cols); i++) {
        float x = float(i) * step;
        float dx1 = x - s1x, dy1 = y - s1y;
        float dx2 = x - s2x, dy2 = y - s2y;
        float d1 = std::sqrt(dx1 * dx1 + dy1 * dy1);
        float d2 = std::sqrt(dx2 * dx2 + dy2 * dy2);
        float v = std::sin(d1 * 0.085f - t * 2.4f) + std::sin(d2 * 0.07f - t * 1.9f);
        float k = (v + 2.0f) * 0.25f;
        int b = int(k * 5.99f);
        if (b < 0) b = 0; if (b > 5) b = 5;
        buckets[b].push_back({x, y + (k - 0.5f) * step * 0.55f * amp});
      }
    }
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    Paint bg; bg.color = Color::argb(0xff03071c);
    c.rect({0, 0, w, h}, bg);
    const uint32_t pal[6] = {0xff0a1b4a, 0xff123a8a, 0xff1f6fd0,
      0xff35b3f0, 0xff7fe9ff, 0xffd9fbff};
    for (int b = 0; b < 6; b++) {
      if (buckets[b].empty()) continue;
      Color cc = Color::argb(pal[b]);
      Paint p; p.blend = Blend::plus;
      p.color = {cc.r, cc.g, cc.b, (0.55f + 0.45f * f.music.energy) * f.intensity};
      c.points(buckets[b], (1.0f + float(b) / 5.0f * step * 0.42f) * 0.5f, p);
    }
  }
};

